      "name": "kpi_theatre",
      "displayName": "kpi_theatre",
      "queryLines": [
        "\n",
        "WITH weekly AS (\n",
        "  SELECT DATE_TRUNC('week', `Session Date`) AS week_start,\n",
        "         MEASURE(`Sessions`)                AS sessions\n",
        "  FROM ramsay_health.ops.mv_theatre_util\n",
        "  WHERE `Session Date` > (SELECT MAX(SessionDate) FROM ramsay_health.ops.fact_theatre_session) - INTERVAL 70 DAYS\n",
        "    AND `Session Date` <= (SELECT MAX(SessionDate) FROM ramsay_health.ops.fact_theatre_session)\n",
        "  GROUP BY 1\n",
        "),\n",
        "med AS (SELECT MEDIAN(sessions) m FROM weekly),\n",
        "full_weeks AS (\n",
        "  SELECT week_start FROM weekly, med WHERE sessions >= 0.5 * med.m\n",
        ")\n",
        "SELECT\n",
        "  ROUND(MEASURE(`Avg Utilisation`), 1)  AS theatre_utilisation_pct,\n",
        "  MEASURE(`Cases Completed`)            AS cases_completed,\n",
        "  MEASURE(`Cancellations`)              AS cancellations\n",
        "FROM ramsay_health.ops.mv_theatre_util\n",
        "WHERE DATE_TRUNC('week', `Session Date`) IN (SELECT week_start FROM full_weeks)\n"
      ]
    },
    {
      "name": "kpi_beds",
      "displayName": "kpi_beds",
      "queryLines": [
        "\n",
        "WITH weekly AS (\n",
        "  SELECT DATE_TRUNC('week', `Bed Date`) AS week_start,\n",
        "         MEASURE(`Admissions`)          AS admissions\n",
        "  FROM ramsay_health.ops.mv_bed_occupancy\n",
        "  WHERE `Bed Date` > (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day) - INTERVAL 70 DAYS\n",
        "    AND `Bed Date` <= (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day)\n",
        "  GROUP BY 1\n",
        "),\n",
        "med AS (SELECT MEDIAN(admissions) m FROM weekly),\n",
        "full_weeks AS (SELECT week_start FROM weekly, med WHERE admissions >= 0.5 * med.m)\n",
        "SELECT\n",
        "  ROUND(MEASURE(`Admissions`) / (SELECT COUNT(*) FROM full_weeks), 0)\n",
        "                                     AS admissions_per_week,\n",
        "  ROUND(MEASURE(`Avg Occupancy`), 1) AS bed_occupancy_pct\n",
        "FROM ramsay_health.ops.mv_bed_occupancy\n",
        "WHERE DATE_TRUNC('week', `Bed Date`) IN (SELECT week_start FROM full_weeks)\n"
      ]
    },
    {
      "name": "kpi_diagnostic",
      "displayName": "kpi_diagnostic",
      "queryLines": [
        "\n",
        "SELECT ROUND(100.0 * SUM(f.SlotsBooked) / NULLIF(SUM(f.SlotsCapacity), 0), 1)\n",
        "         AS diagnostic_booked_pct\n",
        "FROM ramsay_health.ops.fact_diagnostic_slot f\n",
        "JOIN ramsay_health.ops.dim_site d\n",
        "  ON TRY_CAST(f.SiteID AS INT) = TRY_CAST(d.SiteID AS INT)\n",
        "WHERE TO_DATE(f.SlotDate) > (SELECT MAX(TO_DATE(SlotDate)) FROM ramsay_health.ops.fact_diagnostic_slot) - INTERVAL 28 DAYS\n",
        "  AND TO_DATE(f.SlotDate) <= (SELECT MAX(TO_DATE(SlotDate)) FROM ramsay_health.ops.fact_diagnostic_slot)\n"
      ]
    },
    {
      "name": "chart1_util_by_week",
      "displayName": "chart1_util_by_week",
      "queryLines": [
        "\n",
        "WITH weekly AS (\n",
        "  SELECT DATE_TRUNC('week', `Session Date`) AS week_start,\n",
        "         `Site`                             AS site,\n",
        "         MEASURE(`Avg Utilisation`)          AS utilisation_pct,\n",
        "         MEASURE(`Sessions`)                 AS sessions\n",
        "  FROM ramsay_health.ops.mv_theatre_util\n",
        "  WHERE `Session Date` > (SELECT MAX(SessionDate) FROM ramsay_health.ops.fact_theatre_session) - INTERVAL 70 DAYS\n",
        "    AND `Session Date` <= (SELECT MAX(SessionDate) FROM ramsay_health.ops.fact_theatre_session)\n",
        "  GROUP BY 1, 2\n",
        "),\n",
        "med AS (SELECT MEDIAN(sessions) m FROM weekly)\n",
        "SELECT week_start,\n",
        "       site,\n",
        "       ROUND(utilisation_pct, 1) AS utilisation_pct\n",
        "FROM weekly, med\n",
        "WHERE sessions >= 0.5 * med.m      -- drop the partial trailing week\n",
        "ORDER BY week_start, site\n"
      ]
    },
    {
      "name": "chart2_admissions_by_week",
      "displayName": "chart2_admissions_by_week",
      "queryLines": [
        "\n",
        "WITH weekly AS (\n",
        "  SELECT DATE_TRUNC('week', `Bed Date`) AS week_start,\n",
        "         `Site`                          AS site,\n",
        "         MEASURE(`Admissions`)           AS admissions\n",
        "  FROM ramsay_health.ops.mv_bed_occupancy\n",
        "  WHERE `Bed Date` > (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day) - INTERVAL 84 DAYS\n",
        "    AND `Bed Date` <= (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day)\n",
        "  GROUP BY 1, 2\n",
        "),\n",
        "tot AS (\n",
        "  SELECT week_start, SUM(admissions) wk_total FROM weekly GROUP BY 1\n",
        "),\n",
        "med AS (SELECT MEDIAN(wk_total) m FROM tot)\n",
        "SELECT w.week_start, w.site, w.admissions\n",
        "FROM weekly w\n",
        "JOIN tot t ON w.week_start = t.week_start, med\n",
        "WHERE t.wk_total >= 0.5 * med.m    -- drops both the partial tail AND the empty lead weeks\n",
        "ORDER BY w.week_start, w.site\n"
      ]
    },
    {
      "name": "chart3a_bed_occupancy",
      "displayName": "chart3a_bed_occupancy",
      "queryLines": [
        "\n",
        "SELECT `Site` AS site,\n",
        "       ROUND(MEASURE(`Avg Occupancy`), 1) AS occupancy_pct\n",
        "FROM ramsay_health.ops.mv_bed_occupancy\n",
        "WHERE `Bed Date` > (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day) - INTERVAL 28 DAYS\n",
        "  AND `Bed Date` <= (SELECT MAX(BedDate) FROM ramsay_health.ops.fact_bed_day)\n",
        "GROUP BY `Site`\n",
        "ORDER BY occupancy_pct DESC\n"
      ]
    },
    {
      "name": "chart3b_diagnostic",
      "displayName": "chart3b_diagnostic",
      "queryLines": [
        "\n",
        "SELECT d.SiteName AS site,\n",
        "       ROUND(100.0 * SUM(f.SlotsBooked) / NULLIF(SUM(f.SlotsCapacity), 0), 1)\n",
        "         AS booked_pct\n",
        "FROM ramsay_health.ops.fact_diagnostic_slot f\n",
        "JOIN ramsay_health.ops.dim_site d\n",
        "  ON TRY_CAST(f.SiteID AS INT) = TRY_CAST(d.SiteID AS INT)\n",
        "WHERE TO_DATE(f.SlotDate) > (SELECT MAX(TO_DATE(SlotDate)) FROM ramsay_health.ops.fact_diagnostic_slot) - INTERVAL 28 DAYS\n",
        "  AND TO_DATE(f.SlotDate) <= (SELECT MAX(TO_DATE(SlotDate)) FROM ramsay_health.ops.fact_diagnostic_slot)\n",
        "GROUP BY d.SiteName\n",
        "ORDER BY booked_pct DESC\n"
      ]
    },
    {
      "name": "chart4_procedures",
      "displayName": "chart4_procedures",
      "queryLines": [
        "\n",
        "WITH labelled AS (\n",
        "  SELECT CASE WHEN `Procedure Group` IS NULL OR `Procedure Group` = 'null' THEN 'Other/Unmapped' ELSE `Procedure Group` END        AS procedure_group,\n",
        "         `Site`              AS site,\n",
        "         MEASURE(`Revenue`)  AS revenue\n",
        "  FROM ramsay_health.ops.mv_finance_margin\n",
        "  GROUP BY 1, 2\n",
        "),\n",
        "top7 AS (\n",
        "  SELECT procedure_group\n",
        "  FROM labelled\n",
        "  GROUP BY procedure_group\n",
        "  ORDER BY SUM(revenue) DESC\n",
        "  LIMIT 7\n",
        ")\n",
        "SELECT l.procedure_group,\n",
        "       l.site,\n",
        "       ROUND(l.revenue / 1e6, 3) AS revenue_m\n",
        "FROM labelled l\n",
        "JOIN top7 t ON l.procedure_group = t.procedure_group\n",
        "WHERE l.revenue > 0\n",
        "ORDER BY revenue_m DESC\n"
      ]
    }
  ],
